import Link from "next/link";

/** GPUlayer mark: a chip on a stack of layers. docs/assets/logo-mark.svg, generated by
 * scripts/make_logo.py and copied to /docs-assets at build time. An <img> keeps the SVG's
 * gradient and mask ids from clashing when the mark appears several times on a page. */
export function LogoMark({ className = "h-6 w-6" }: { className?: string }) {
  // eslint-disable-next-line @next/next/no-img-element
  return <img src="/docs-assets/logo-mark.svg" alt="" aria-hidden className={className} />;
}

export function Logo() {
  return (
    <Link href="/" className="flex items-center gap-2 tracking-tight" aria-label="GPUlayer home">
      <LogoMark />
      <span className="text-[17px]">
        <span className="font-bold">GPU</span>
        <span className="font-medium text-muted-foreground">layer</span>
      </span>
    </Link>
  );
}
